<template>
  <HoverCard>
    <HoverCardTrigger>
      <div class="flex items-center gap-2 cursor-pointer">
        <ListChecksIcon
          :class="['w-5 h-5 stroke-accent-foreground', state.count === state.max_count && 'stroke-success-foreground']"
        />
        <span>{{ state.count }}/{{ state.max_count }}</span>
      </div>
    </HoverCardTrigger>
    <HoverCardContent>
      <div v-for="item in checkmarks" :key="item.id" class="flex items-center justify-start py-2">
        <CheckIcon v-if="item.value" class="min-w-5 max-w-5 h-5 stroke-green-600 inline" />
        <XIcon v-else class="min-w-5 max-w-5 h-5 stroke-red-600 inline" />
        <p class="ml-2 text-sm">{{ item.label }}</p>
      </div>
    </HoverCardContent>
  </HoverCard>
</template>

<script setup lang="ts" generic="CheckmarkT extends string">
import { CheckIcon, ListChecksIcon, XIcon } from 'lucide-vue-next';

interface Props {
  state: {
    // Partial: a concrete state shape may cover only some of `order` (e.g. the
    // subcontractor onboarding state has just two of the ten checkmarks).
    // Keys absent from the state are skipped below rather than rendered as unchecked.
    checkmarks: Partial<Record<NoInfer<CheckmarkT>, boolean>>;
    count: number;
    max_count: number;
  };
  order: CheckmarkT[];
  labelMap: (checkmark: CheckmarkT) => { label: string };
}

const props = defineProps<Props>();

const checkmarks = computed(() => {
  const state = props.state.checkmarks;
  return props.order.flatMap((id) => {
    if (!(id in state)) return [];
    return [{ id, label: props.labelMap(id).label, value: state[id] }];
  });
});
</script>

<style scoped lang="scss"></style>
