<template>
  <Popover>
    <PopoverAnchor class="relative">
      <PopoverTrigger as-child>
        <Button
          variant="outline"
          :disabled="isDisabled"
          :class="cn('h-10 font-normal w-full justify-between', isCheckSelected ? '' : 'text-muted-foreground')"
        >
          <span class="inline-flex items-center overflow-hidden">
            <FilterIcon class="me-2 h-4 w-4 shrink-0" />
            <span v-if="isDisabled" class="line-clamp-1">{{ emptyText }}</span>
            <span v-else-if="checksCount === 0" :class="cn('line-clamp-1')">All {{ entityNamePlural }}</span>
            <span v-else-if="checksCount === 1" class="line-clamp-1">1 {{ entityName }}</span>
            <span v-else class="line-clamp-1">{{ checksCount }} {{ entityNamePlural }}</span>
          </span>
          <ChevronsUpDownIcon class="opacity-50" :class="isCheckSelected ? 'mr-6' : ''" />
        </Button>
      </PopoverTrigger>
      <XIcon
        v-if="isCheckSelected && !isDisabled"
        role="button"
        :aria-label="`Clear ${entityName} filter`"
        tabindex="0"
        class="h-4 w-4 shrink-0 absolute right-4 top-[0.75rem] cursor-pointer"
        @click.stop.prevent="clearCheckmarks"
        @keydown.enter.space.prevent="clearCheckmarks"
      />
    </PopoverAnchor>
    <PopoverContent class="max-h-[min(20rem,_calc(var(--reka-popover-content-available-height)-10px))] overflow-y-auto">
      <div v-for="(item, index) in checkmarks" :key="item.id" class="flex items-center justify-start p-2">
        <TriStateCheckbox
          :id="item.id"
          v-model="checkmarks[index].value"
          class="mr-2"
          @update:model-value="onCheckmarkUpdate"
        />
        <Label :for="item.id" class="w-full">{{ item.label }}</Label>
      </div>
    </PopoverContent>
  </Popover>
</template>
<script setup lang="ts" generic="CheckmarkT extends string">
import { ChevronsUpDownIcon, FilterIcon, XIcon } from 'lucide-vue-next';
import { PopoverAnchor } from 'reka-ui';
import { cn } from '@/lib/utils';
import type { LocationQuery, LocationQueryRaw } from 'vue-router';

interface Props {
  entityName: string;
  entityNamePlural: string;
  value: { checkmark: CheckmarkT; value: boolean }[];
  order: CheckmarkT[];
  labelMap: (checkmark: CheckmarkT) => { label: string };
  queryBuild: (currentQuery: LocationQuery, filters: { checkmark: CheckmarkT; value: boolean }[]) => LocationQueryRaw;
  emptyText: string;
}

const props = defineProps<Props>();

const route = useRoute();

type CheckmarkRow = { id: CheckmarkT; label: string; value: boolean | 'indeterminate' };

const checkmarks = computed<CheckmarkRow[]>(() => {
  const rows: CheckmarkRow[] = props.order.map((id) => ({
    id,
    label: props.labelMap(id).label,
    value: 'indeterminate',
  }));
  props.value.forEach((filter) => {
    const row = rows.find((r) => r.id === filter.checkmark);
    if (row) {
      row.value = filter.value;
    }
  });
  return rows;
});

function onCheckmarkUpdate() {
  const processed = checkmarks.value
    .filter((x) => x.value !== 'indeterminate')
    .map((x) => ({ checkmark: x.id, value: x.value as boolean }));
  navigateTo({ query: props.queryBuild(route.query, processed) });
}

// Clearing writes an empty selection to the URL, which strips every key, so
// `value` resets to [] and the computed re-derives all rows back to 'indeterminate'.
function clearCheckmarks() {
  navigateTo({ query: props.queryBuild(route.query, []) });
}

const checksCount = computed(() => checkmarks.value.filter((x) => x.value !== 'indeterminate').length);

const isCheckSelected = computed(() => checksCount.value > 0);

const isDisabled = computed(() => props.order.length === 0);
</script>
