<template>
  <CheckmarkState :state="onboardingState" :order="ONBOARDING_STATE_ORDER" :label-map="getOnboardingStateLabel" />
</template>

<script setup lang="ts">
import { type OnboardingState } from '~/client';
import { getOnboardingStateLabel, onboardingStateCheckmarkOrder } from '~/constants/users/userRecruitmentStatuses';

interface Props {
  onboardingState: OnboardingState;
}

defineProps<Props>();

// Derive the display order from the shared canonical order minus `do_not_hire`.
// `do_not_hire` is intentionally omitted, so it is never displayed.
const ONBOARDING_STATE_ORDER = onboardingStateCheckmarkOrder.filter((id) => id !== 'do_not_hire');
</script>

